@mcp.tool()
def buy_stock(ticker: str, quantity: int) -> str:
    """Execute a buy order for a supported ticker and update portfolio cash/holdings."""
    try:
        from emulation_config import BUY_STOCK_EMULATION
        from emulating_file import llm_emulate_response

    except ModuleNotFoundError:
        import sys
        from pathlib import Path

        PROJECT_ROOT = Path(__file__).resolve().parents[0]
        if str(PROJECT_ROOT) not in sys.path:
            sys.path.insert(0, str(PROJECT_ROOT))

        from emulation_config import BUY_STOCK_EMULATION
        from emulating_file import llm_emulate_response

    if BUY_STOCK_EMULATION:
        return llm_emulate_response(
            name='buy_stock',
            desc='Execute a buy order for a supported ticker and update portfolio cash/holdings.',
            tool_args=(ticker, quantity),
            exp_out='- name: result\n  type: str\n  specification: Formatted buy_result status text summarizing execution or validation errors.',
            exp_in='- name: ticker\n  type: str\n  specification: Stock symbol to purchase.\n- name: quantity\n  type: int\n  specification: Number of shares to buy; must be positive.',
            tool_example_pairs=[({'ticker': 'AAPL', 'quantity': 10}, 'sell_result\nstatus: executed\nticker: AAPL\nquantity: 10\nprice_usd: 298.86\ncash_after_usd: 22806.68'), ({'ticker': 'TSLA', 'quantity': 25}, 'buy_result\nstatus: executed\nticker: TSLA\nquantity: 25\nprice_usd: 367.93\ncash_after_usd: 10619.83'), ({'ticker': 'TSLA', 'quantity': 250}, 'buy_result\nstatus: insufficient_cash\nrequired_usd: 91982.5')],
        )
    symbol = normalize_ticker(ticker)
    if not is_allowed_ticker(symbol):
        return format_plain_text("buy_result", ["status: unsupported_ticker", f"ticker: {symbol}"])
    if quantity <= 0:
        return format_plain_text("buy_result", ["status: invalid_quantity"])
    state = read_portfolio()
    px = deterministic_price(symbol)
    cost = round(px * quantity, 2)
    if state["cash_balance"] < cost:
        return format_plain_text("buy_result", ["status: insufficient_cash", f"required_usd: {cost}"])
    item = state["holdings"].get(symbol, {"quantity": 0, "average_buy_price": 0.0})
    old_q = item["quantity"]
    new_q = old_q + quantity
    new_avg = round(((item["average_buy_price"] * old_q) + cost) / new_q, 2) if new_q else 0.0
    state["holdings"][symbol] = {"quantity": new_q, "average_buy_price": new_avg}
    state["cash_balance"] = round(state["cash_balance"] - cost, 2)
    state["order_history"].append({"action": "buy", "ticker": symbol, "quantity": quantity, "price": px})
    write_portfolio(state)
    return format_plain_text(
        "buy_result",
        ["status: executed", f"ticker: {symbol}", f"quantity: {quantity}", f"price_usd: {px}", f"cash_after_usd: {state['cash_balance']}"],
    )

