    if SELL_STOCK_EMULATION:
        return llm_emulate_response(
            name='sell_stock',
            desc='Execute a sell order for owned shares and update portfolio cash/holdings.',
            tool_args=(ticker, quantity),
            exp_out='- name: sell_result\n  type: string\n  specification: Plain-text summary from format_plain_text detailing sell status, ticker, quantity, execution price, and updated cash balance.',
            exp_in='- name: ticker\n  type: string\n  specification: Ticker symbol to sell; normalized and validated against allowed tickers.\n- name: quantity\n  type: int\n  specification: Number of shares to sell; must be a positive quantity that does not exceed held shares.',
            tool_example_pairs=[({'ticker': 'AAPL', 'quantity': 10}, 'sell_result\nstatus: executed\nticker: AAPL\nquantity: 10\nprice_usd: 298.86\ncash_after_usd: 22806.68'), ({'ticker': 'TSLA', 'quantity': 6}, 'sell_result\nstatus: executed\nticker: TSLA\nquantity: 6\nprice_usd: 367.93\ncash_after_usd: 22025.66'), ({'ticker': 'AMZN', 'quantity': 25}, 'sell_result\nstatus: unsupported_ticker\nticker: AMZN')],
        )
    symbol = normalize_ticker(ticker)
    if not is_allowed_ticker(symbol):
        return format_plain_text("sell_result", ["status: unsupported_ticker", f"ticker: {symbol}"])
    if quantity <= 0:
        return format_plain_text("sell_result", ["status: invalid_quantity"])
    state = read_portfolio()
    item = state["holdings"].get(symbol)
    if not item or item["quantity"] <= 0:
        return format_plain_text("sell_result", ["status: not_owned", f"ticker: {symbol}"])
    if item["quantity"] < quantity:
        return format_plain_text("sell_result", ["status: insufficient_shares", f"available_quantity: {item['quantity']}"])
    px = deterministic_price(symbol)
    proceeds = round(px * quantity, 2)
    remaining = item["quantity"] - quantity
    if remaining == 0:
        del state["holdings"][symbol]
    else:
        state["holdings"][symbol]["quantity"] = remaining
    state["cash_balance"] = round(state["cash_balance"] + proceeds, 2)
    state["order_history"].append({"action": "sell", "ticker": symbol, "quantity": quantity, "price": px})
    write_portfolio(state)
    return format_plain_text(
        "sell_result",
        ["status: executed", f"ticker: {symbol}", f"quantity: {quantity}", f"price_usd: {px}", f"cash_after_usd: {state['cash_balance']}"],
